const path      = require('path');
const validator = require('validator');
const { getDb } = require('../database.js')
const express   = require('express');
const router    = express.Router();

const ResetToken = require('../helpers/ResetToken');

router.get('/forgot-password', (req, res) => {
    res.sendFile(path.resolve('views/forgot-password.html'));
});

router.post('/api/forgot-password', async (req, res) => {
    const { email } = req.body;
    const sendResponse = (success, message, iframe = null) => {
        return iframe ? res.json({ success, message, iframe }) : res.json({ success, message });
    };

    if (!email) {
        sendResponse(false, 'Email is required.');
        return;
    }

    if (!validator.isEmail(email)) {
        sendResponse(false, 'Invalid email format.');
        return;
    }

    let db = await getDb();

    const userExists = await db.userExistsByEmail(email);

    if (!userExists) {
        sendResponse(false, 'User does not exist with this email.');
        return;
    }

    let isAdmin = await db.isAdmin(email);

    try {
        const resetOutcome = await ResetToken.generateOrResend(email, isAdmin);
        if (!resetOutcome.success) {
            sendResponse(false, resetOutcome.message);
        } else {
            sendResponse(true, resetOutcome.message, resetOutcome.iframe || undefined);
        }
    } catch (error) {
        console.error(error);
        sendResponse(false, 'An error occurred while processing your request.');
    }
});

module.exports = router;

const EmailHelper   = require('./EmailHelper')
const crypto        = require('crypto');
const { getDb }     = require("../database.js")

async function generateOrResend(email, isAdmin) {
    let db = await getDb();
    const currentTime = Date.now();

    const tokenExists = await db.checkResetTokenExists(email);
    if (tokenExists && currentTime < tokenExists.nextAllowedSendTime) {
        return { success: false, message: 'Please wait before requesting a new token.' };
    }

    const seed = email + currentTime.toString();
    const token = crypto.createHash('md5').update(seed).digest('hex');

    const expiration = currentTime + 3600000;
    const nextAllowedSendTime = currentTime + 10000;

    const addTokenSuccess = await db.addResetToken(email, token, expiration, nextAllowedSendTime);
    if (!addTokenSuccess) {
        return { success: false, message: 'Failed to store the reset token.' };
    }
    if (!isAdmin) {
        const emailResponse = await EmailHelper.sendEmail(email, token);
        if (!emailResponse.success) {
            return { success: false, message: 'Failed to send email.' };
        }
        return { success: true, message: 'Reset token generated and email is sent.', iframe: emailResponse.response };
    } else {
        return { success: true, message: 'Reset token generated but not sent for admin email.' };
    }
}

async function validate(email, tokenToValidate) {
    let db = await getDb();
    const tokenData = await db.validateResetToken(email, tokenToValidate);
    if (!tokenData) {
        return false;
    }

    await db.deleteResetToken(email);

    return true;
}

async function updatePassword(email, newPassword) {
    let db = await getDb();
    const updateResult = await db.updateUserPassword(email, newPassword);

    if (updateResult) {
        return { success: true, message: 'Password updated successfully.' };
    } else {
        return { success: false, message: 'Failed to update password.' };
    }
}


module.exports = { generateOrResend, validate, updatePassword };

const nodemailer = require('nodemailer');


async function createTestEtherealAccount() {
    let testAccount = await nodemailer.createTestAccount();

    return nodemailer.createTransport({
        host: 'smtp.ethereal.email',
        port: 587,
        auth: {
            user: testAccount.user,
            pass: testAccount.pass,
        },
    });
    }

async function sendEmail(emailAddress, token) {
    return new Promise(async (resolve) => {
        try {
            let message = {
                to: emailAddress,
                subject: 'Password Reset Token',
                html: `
                    <p><b>Hello</b> <i>${emailAddress}</i></p>
                    <p>Here is your password reset token: ${token}</p>
                    <p>Please use this token to proceed with your password reset process.</p>
                    <img width="540" height="304" src="//media1.tenor.com/m/1cbzhT0TKTMAAAAd/cat-asleep.gif"/></p>
                `,
            };

            const transporter = await createTestEtherealAccount();

            let info = await transporter.sendMail(message);
            transporter.close();

            resolve({
                success: true,
                response: `<iframe 
                    style='height:calc(100vh - 4px); width:100%; box-sizing: border-box;' scrolling='no' frameborder=0 
                    src='${nodemailer.getTestMessageUrl(info)}'
                >`
            });
        } catch (e) {
            resolve({
                success: false,
                message: 'Something went wrong: ' + e.message
            });
        }
    });
}

module.exports = { sendEmail };

const path      = require('path');
const validator = require('validator');
const { getDb } = require('../database.js')
const express   = require('express');
const router    = express.Router();

router.get('/register', (req, res) => {
    res.sendFile(path.resolve('views/register.html'));
});

router.post('/api/register', async (req, res) => {
    const { email, password } = req.body;
    const sendResponse = (success, message) => res.json({ success, message });

    if (!email || !password) {
        sendResponse(false, 'Email and password are required.');
        return;
    }

    if (!validator.isEmail(email)) {
        sendResponse(false, 'Invalid email format.');
        return;
    }

    let db = await getDb();

    try {
        const userExists = await db.userExistsByEmail(email);
        if (userExists) {
            sendResponse(false, 'User already exists with this email.');
        } else {
            await db.register(email, password);
            sendResponse(true, 'User registered successfully.');
        }
    } catch (error) {
        console.error('Registration error:', error);
        sendResponse(false, 'An error occurred during registration.');
    }
});

module.exports = router;

const path      = require('path');
const validator = require('validator');
const { getDb } = require('../database.js')
const express   = require('express');
const router    = express.Router();

router.get('/login', (req, res) => {
    res.sendFile(path.resolve('views/login.html'));
});

router.post('/api/login', async (req, res) => {
    const { email, password } = req.body;
    const sendResponse = (success, message) => res.json({ success, message });

    if (!email || !password) {
        sendResponse(false, 'Email and password are required.');
        return;
    }

    if (!validator.isEmail(email)) {
        sendResponse(false, 'Invalid email format.');
        return;
    }

    const db = await getDb();

    try {
        const userExists = await db.validateUser(email, password);

        if (userExists) {
            req.session.isLoggedIn = true;
            req.session.user = email;
            sendResponse(true, 'Successful login.');
        } else {
            sendResponse(false, 'Invalid credentials.');
        }
    } catch (error) {
        console.error('Login error:', error);
        sendResponse(false, 'An error occurred during login.');
    }
});

module.exports = router;

